#!/bin/bash
#SBATCH --job-name=ALS_important_QTL_plots
#SBATCH --output=/home/zw529/donglab/data/target_ALS/QTL/important_QTL_plots_%j.out
#SBATCH --error=/home/zw529/donglab/data/target_ALS/QTL/important_QTL_plots_%j.err
#SBATCH --partition=week
#SBATCH --time=5-23:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=80G

# Standalone plotting-only job; run after generate_important_SNP_table.sh.
# All plotting helpers are compressed below and unpacked automatically at runtime.
# Evidence tables, priorities and scores are read only.
set -euo pipefail
module load deepTools
module load R
command -v samtools >/dev/null
command -v Rscript >/dev/null
python -c 'import numpy,pandas,matplotlib,pyBigWig,scipy'
Rscript -e 'stopifnot(requireNamespace("ggplot2",quietly=TRUE),requireNamespace("gridExtra",quietly=TRUE),requireNamespace("data.table",quietly=TRUE))'
python -u - "$@" <<'PLOTTING_ONLY_PYTHON'
import base64, json, lzma, subprocess, sys, tempfile
from pathlib import Path
